#!/usr/bin/env node
/**
 * One source of truth for the app version: package.json.
 *
 *   node scripts/version.mjs sync          derive every generated file
 *   node scripts/version.mjs set 0.0.49    set package.json, then sync
 *   node scripts/version.mjs check         fail when anything drifted
 */
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const root = path.resolve(fileURLToPath(new URL('..', import.meta.url)))
const packagePath = path.join(root, 'package.json')
const lockPath = path.join(root, 'package-lock.json')
const gradlePath = path.join(root, 'android/app/build.gradle')
const versionPath = path.join(root, 'src/version.ts')
const readmePath = path.join(root, 'README.md')

function readJson(file) {
  return JSON.parse(fs.readFileSync(file, 'utf8'))
}

function writeJson(file, value) {
  fs.writeFileSync(file, `${JSON.stringify(value, null, 2)}\n`)
}

function parseVersion(value) {
  const match = /^(\d+)\.(\d+)\.(\d+)$/.exec(String(value || '').trim())
  if (!match) throw new Error(`Version must look like 1.2.3, got: ${value}`)
  return { major: Number(match[1]), minor: Number(match[2]), patch: Number(match[3]) }
}

function versionCode(parts) {
  return parts.major * 1_000_000 + parts.minor * 1_000 + parts.patch
}

function versionTs(version) {
  return `// Generated by scripts/version.mjs. Do not edit by hand.\nexport const APP_VERSION = '${version}'\n`
}

function syncReadme(text, version) {
  return text
    .replace(/Icyteru-\d+\.\d+\.\d+\.apk/g, `Icyteru-${version}.apk`)
    .replace(/Icyteru Setup \d+\.\d+\.\d+\.exe/g, `Icyteru Setup ${version}.exe`)
}

function currentVersion() {
  return String(readJson(packagePath).version || '').trim()
}

function sync() {
  const version = currentVersion()
  const code = versionCode(parseVersion(version))

  const gradle = fs.readFileSync(gradlePath, 'utf8')
  if (!/versionCode\s+\d+/.test(gradle) || !/versionName\s+"[^"]+"/.test(gradle)) {
    throw new Error('Could not find versionCode/versionName in android/app/build.gradle')
  }
  const nextGradle = gradle
    .replace(/versionCode\s+\d+/, `versionCode ${code}`)
    .replace(/versionName\s+"[^"]+"/, `versionName "${version}"`)
  fs.writeFileSync(gradlePath, nextGradle)

  fs.writeFileSync(versionPath, versionTs(version))

  const lock = readJson(lockPath)
  lock.version = version
  if (lock.packages && lock.packages['']) lock.packages[''].version = version
  writeJson(lockPath, lock)

  const readme = fs.readFileSync(readmePath, 'utf8')
  const nextReadme = syncReadme(readme, version)
  if (nextReadme !== readme) fs.writeFileSync(readmePath, nextReadme)

  console.log(`version synced: ${version} (versionCode ${code})`)
}

function check() {
  const version = currentVersion()
  const code = versionCode(parseVersion(version))
  const problems = []

  const gradle = fs.readFileSync(gradlePath, 'utf8')
  if (!new RegExp(`versionCode\\s+${code}\\b`).test(gradle)) {
    problems.push(`android/app/build.gradle versionCode must be ${code}`)
  }
  if (!gradle.includes(`versionName "${version}"`)) {
    problems.push(`android/app/build.gradle versionName must be "${version}"`)
  }

  const generated = fs.readFileSync(versionPath, 'utf8').replace(/\r\n/g, '\n').trim()
  if (generated !== versionTs(version).trim()) {
    problems.push(`src/version.ts must contain APP_VERSION = '${version}'`)
  }

  const lock = readJson(lockPath)
  if (lock.version !== version) problems.push(`package-lock.json version must be ${version}`)
  if (lock.packages?.['']?.version !== version) {
    problems.push(`package-lock.json packages[""].version must be ${version}`)
  }

  const readme = fs.readFileSync(readmePath, 'utf8')
  if (!readme.includes(`Icyteru-${version}.apk`)) {
    problems.push(`README.md must mention Icyteru-${version}.apk`)
  }

  if (problems.length) {
    console.error(`Version drift for ${version}:`)
    for (const problem of problems) console.error(`- ${problem}`)
    process.exit(1)
  }
  console.log(`version check ok: ${version} (versionCode ${code})`)
}

const mode = process.argv[2] || 'check'
if (mode === 'sync') {
  sync()
} else if (mode === 'check') {
  check()
} else if (mode === 'set') {
  const version = String(process.argv[3] || '').trim()
  parseVersion(version)
  const packageJson = readJson(packagePath)
  packageJson.version = version
  writeJson(packagePath, packageJson)
  sync()
} else {
  console.error('Usage: node scripts/version.mjs <sync|check|set> [version]')
  process.exit(2)
}
